  text4: " qua kẽ lá, rọi xuống mặt nước ",
  text5: ". Cả khu rừng như bừng tỉnh sau một đêm dài yên giấc.",
  bank: ["chìm","rộn ràng","len lỏi","long lanh","khô khốc"],
  answers: ["chìm","rộn ràng","len lỏi","long lanh"]
